//! Two-stage page-table lookup for Unicode scalar properties.
//!
//! `data.bin` is generated by `tools/unicode/properties/generate_data.py`.
//! Each scalar maps to one packed `u64`: five `General_Category` bits plus one
//! bit per binary property. The 256-scalar pages are deduplicated, so a lookup
//! is one index load and one payload load instead of a binary search.
//!
//! `set_ranges.bin` is generated from `data.bin` by
//! `tools/unicode/properties/generate_set_ranges.py`. It holds the coalesced
//! scalar ranges for every property bit and category mask, letting set
//! construction copy ranges instead of rescanning every deduplicated page.

const std = @import("std");

const data = @embedFile("data.bin");

/// Exact Unicode 17.0 `General_Category` values.
///
/// Declaration order is part of the generated binary format. The generator
/// records a fingerprint of this enum in the blob header so reordering it
/// without regenerating the data fails at compile time.
pub const Category = enum(u5) {
    Lu,
    Ll,
    Lt,
    Lm,
    Lo,
    Mn,
    Mc,
    Me,
    Nd,
    Nl,
    No,
    Pc,
    Pd,
    Ps,
    Pe,
    Pi,
    Pf,
    Po,
    Sm,
    Sc,
    Sk,
    So,
    Zs,
    Zl,
    Zp,
    Cc,
    Cf,
    Cs,
    Co,
    Cn,
};

pub const all_category_mask: u32 = 0x3fff_ffff;

const header_len = 16;
const index_count = readU16(8);
const page_count = readU16(10);
const index_offset = header_len;
const pages_offset = index_offset + @as(usize, index_count) * 2;

const default_value: u64 = @intFromEnum(Category.Cn);

comptime {
    if (data.len < header_len or !std.mem.eql(u8, data[0..4], "CJP2") or
        data[4] != 2 or data[5] != 17 or data[6] != 0 or data[7] != 0)
    {
        @compileError("invalid Unicode property data");
    }
    if (index_count != 0x1100 or
        pages_offset + @as(usize, page_count) * 256 * 8 != data.len)
    {
        @compileError("invalid Unicode property data lengths");
    }
    if (readU32(12) != categoryFingerprint()) {
        @compileError(
            "Unicode property data was generated for a different Category enum",
        );
    }
}

const ascii_values = buildAsciiValues();

/// Flat `General_Category` table derived from `data.bin`. The category query
/// uses one load instead of the packed table's dependent index-then-page
/// loads, which dominate random lookups.
const flat_categories = @embedFile("flat_categories.bin");
const flat_header_len = 16;
const flat_count = readU32At(flat_categories, 8);

comptime {
    if (flat_categories.len < flat_header_len or
        !std.mem.eql(u8, flat_categories[0..4], "CJZ7") or
        flat_categories[4] != 1 or
        flat_categories[5] != 17 or
        flat_categories[6] != 0 or
        flat_categories[7] != 0)
    {
        @compileError("invalid flat General_Category data");
    }
    if (flat_count != 0x110001 or
        flat_header_len + flat_count != flat_categories.len)
    {
        @compileError("invalid flat General_Category data lengths");
    }
}

const set_ranges = @embedFile("set_ranges.bin");
const sr_header_len = 16;
const sr_property_count = readU16At(set_ranges, 8);
const sr_mask_count = readU16At(set_ranges, 10);
const sr_range_count = readU32At(set_ranges, 12);
const sr_property_offset = sr_header_len;
const sr_mask_offset = sr_property_offset + @as(usize, sr_property_count) * 8;
const sr_ranges_offset = sr_mask_offset + @as(usize, sr_mask_count) * 12;

comptime {
    if (set_ranges.len < sr_header_len or
        !std.mem.eql(u8, set_ranges[0..4], "CJSR") or
        set_ranges[4] != 1 or
        set_ranges[5] != 17 or set_ranges[6] != 0 or set_ranges[7] != 0)
    {
        @compileError("invalid precomputed set range data");
    }
    if (sr_property_count != 64 or
        sr_ranges_offset + @as(usize, sr_range_count) * 8 != set_ranges.len)
    {
        @compileError("invalid precomputed set range data lengths");
    }
}

fn buildAsciiValues() [128]u64 {
    @setEvalBranchQuota(10_000);
    var values: [128]u64 = undefined;
    var codepoint: u21 = 0;
    while (codepoint < 128) : (codepoint += 1) {
        values[codepoint] = rawValue(codepoint);
    }
    return values;
}

inline fn rawValue(codepoint: u21) u64 {
    const page = @as(usize, codepoint) >> 8;
    const slot = readU16(index_offset + page * 2);
    return readU64(
        pages_offset + (@as(usize, slot) * 256 +
            (@as(usize, codepoint) & 0xff)) * 8,
    );
}

/// Return the packed property word for one scalar value.
///
/// ASCII is served from a compile-time materialized first page; values above
/// the Unicode range resolve to `Cn` with every binary flag cleared.
pub inline fn value(codepoint: u21) u64 {
    if (codepoint < 0x80) return ascii_values[codepoint];
    if (codepoint > 0x10ffff) return default_value;
    return rawValue(codepoint);
}

/// Test one binary-property bit in the packed property word.
pub inline fn has(codepoint: u21, bit_index: u6) bool {
    return (value(codepoint) & (@as(u64, 1) << bit_index)) != 0;
}

pub inline fn category(codepoint: u21) Category {
    // The generator appends a `Cn` sentinel for scalars above U+10FFFF, so a
    // clamped load matches `value`'s default without a branch.
    const index: usize = @min(
        @as(usize, codepoint),
        @as(usize, flat_count) - 1,
    );
    return @enumFromInt(flat_categories[flat_header_len + index]);
}

pub fn categoryMask(category_value: Category) u32 {
    return @as(u32, 1) << @intFromEnum(category_value);
}

pub inline fn matchesMask(codepoint: u21, mask: u32) bool {
    return (categoryMask(category(codepoint)) & mask) != 0;
}

/// Emit the inclusive scalar ranges selected by a category mask and/or
/// binary-property mask, in ascending order.
///
/// The packed word stores the `General_Category` ordinal in bits 0..4, so
/// category selection tests a one-hot bit derived from that ordinal, while
/// binary properties test their own bit directly.
///
/// Pages are deduplicated in the blob, so membership is materialized once
/// per distinct page instead of once per scalar. Run extraction then works
/// on the 256-bit page masks, which keeps whole-property set construction
/// proportional to the number of ranges rather than to the 1.1M scalars.
///
/// `emit` must append the ranges unchanged: they are already coalesced and
/// non-adjacent.
pub fn forEachRun(
    category_mask: u32,
    property_mask: u64,
    context: anytype,
    comptime emit: anytype,
) !void {
    var slot_words: [page_count][4]u64 = undefined;
    var slot_ready = [_]bool{false} ** page_count;
    var run_start: u32 = 0;
    var run_open = false;

    var page: usize = 0;
    while (page < index_count) : (page += 1) {
        const slot = readU16(index_offset + page * 2);
        if (!slot_ready[slot]) {
            const base = pages_offset + @as(usize, slot) * 256 * 8;
            var words: [4]u64 = .{ 0, 0, 0, 0 };
            if (category_mask == 0) {
                // Binary-property-only sets dominate set construction; the
                // category test would be dead work on every scalar.
                var index: usize = 0;
                while (index < 256) : (index += 1) {
                    if ((readU64(base + index * 8) & property_mask) != 0) {
                        words[index >> 6] |=
                            @as(u64, 1) << @intCast(index & 63);
                    }
                }
            } else {
                var index: usize = 0;
                while (index < 256) : (index += 1) {
                    const word_value = readU64(base + index * 8);
                    const selected = (word_value & property_mask) != 0 or
                        ((@as(u64, 1) << @as(u6, @intCast(word_value & 0x1f))) &
                            category_mask) != 0;
                    if (selected) {
                        words[index >> 6] |=
                            @as(u64, 1) << @intCast(index & 63);
                    }
                }
            }
            slot_words[slot] = words;
            slot_ready[slot] = true;
        }

        const page_base: u32 = @intCast(page * 256);
        for (slot_words[slot], 0..) |word, word_index| {
            const word_base = page_base + @as(u32, @intCast(word_index)) * 64;
            if (run_open and (word & 1) == 0) {
                try emit(context, @intCast(run_start), @intCast(word_base - 1));
                run_open = false;
            }
            var remaining = word;
            while (remaining != 0) {
                const start: u32 = @ctz(remaining);
                const tail = remaining >> @intCast(start);
                const len: u32 = @ctz(~tail);
                if (!run_open) {
                    run_start = word_base + start;
                    run_open = true;
                }
                if (start + len < 64) {
                    try emit(
                        context,
                        @intCast(run_start),
                        @intCast(word_base + start + len - 1),
                    );
                    run_open = false;
                    remaining &= ~((@as(u64, 1) << @intCast(start + len)) - 1);
                } else {
                    remaining = 0;
                }
            }
        }
    }
    if (run_open) {
        try emit(context, @intCast(run_start), 0x10ffff);
    }
}

fn readU16(offset: usize) u16 {
    return std.mem.readInt(u16, data[offset..][0..2], .little);
}

fn readU32(offset: usize) u32 {
    return std.mem.readInt(u32, data[offset..][0..4], .little);
}

fn readU64(offset: usize) u64 {
    return std.mem.readInt(u64, data[offset..][0..8], .little);
}

fn readU16At(blob: []const u8, offset: usize) u16 {
    return std.mem.readInt(u16, blob[offset..][0..2], .little);
}

fn readU32At(blob: []const u8, offset: usize) u32 {
    return std.mem.readInt(u32, blob[offset..][0..4], .little);
}

/// One precomputed range list inside `set_ranges.bin`.
pub const RangeEntry = struct {
    offset: u32,
    count: u32,
};

/// Precomputed ranges selected by one binary-property bit.
pub fn propertyRangeEntry(bit: u6) RangeEntry {
    const base = sr_property_offset + @as(usize, bit) * 8;
    return .{
        .offset = readU32At(set_ranges, base),
        .count = readU32At(set_ranges, base + 4),
    };
}

pub const MaskEntry = struct {
    mask: u32,
    ranges: RangeEntry,
};

/// Number of precomputed category masks (single categories and aggregates).
pub fn maskEntryCount() usize {
    return sr_mask_count;
}

pub fn maskEntryAt(index: usize) MaskEntry {
    const base = sr_mask_offset + index * 12;
    return .{
        .mask = readU32At(set_ranges, base),
        .ranges = .{
            .offset = readU32At(set_ranges, base + 4),
            .count = readU32At(set_ranges, base + 8),
        },
    };
}

/// Precomputed ranges for a `General_Category` mask, or null when the mask is
/// not one of the single-category or aggregate aliases. Entries are sorted by
/// mask, so the scan can stop early.
pub fn maskRangeEntry(mask: u32) ?RangeEntry {
    var index: usize = 0;
    while (index < sr_mask_count) : (index += 1) {
        const entry = maskEntryAt(index);
        if (entry.mask == mask) return entry.ranges;
        if (entry.mask > mask) return null;
    }
    return null;
}

pub fn rangeFirst(entry: RangeEntry, index: usize) u21 {
    const base = sr_ranges_offset + (@as(usize, entry.offset) + index) * 8;
    return @intCast(readU32At(set_ranges, base));
}

pub fn rangeLast(entry: RangeEntry, index: usize) u21 {
    const base = sr_ranges_offset + (@as(usize, entry.offset) + index) * 8;
    return @intCast(readU32At(set_ranges, base + 4));
}

/// Raw little-endian bytes of one entry's range list. Each record is two
/// `u32` scalars, matching the in-memory layout of a set range on
/// little-endian targets.
pub fn rangeBytes(entry: RangeEntry) []const u8 {
    const start = sr_ranges_offset + @as(usize, entry.offset) * 8;
    return set_ranges[start..][0 .. @as(usize, entry.count) * 8];
}

fn categoryFingerprint() u32 {
    @setEvalBranchQuota(10_000);
    var hash: u32 = 2166136261;
    inline for (@typeInfo(Category).@"enum".fields) |field| {
        for (field.name) |byte| {
            hash = (hash ^ byte) *% 16777619;
        }
        hash = (hash ^ 0xff) *% 16777619;
    }
    return hash;
}

test "precomputed set ranges match the page scan" {
    const testing = @import("std").testing;
    const allocator = testing.allocator;

    const Collector = struct {
        allocator: std.mem.Allocator,
        ranges: std.ArrayList(Pair) = .empty,

        const Pair = struct {
            first: u21,
            last: u21,
        };

        fn append(context: *@This(), first: u21, last: u21) !void {
            try context.ranges.append(context.allocator, .{
                .first = first,
                .last = last,
            });
        }
    };

    var bit: u6 = 5;
    while (true) : (bit += 1) {
        var collector: Collector = .{ .allocator = allocator };
        defer collector.ranges.deinit(allocator);
        try forEachRun(0, @as(u64, 1) << bit, &collector, Collector.append);
        const entry = propertyRangeEntry(bit);
        try testing.expectEqual(
            @as(usize, entry.count),
            collector.ranges.items.len,
        );
        for (collector.ranges.items, 0..) |range, index| {
            try testing.expectEqual(range.first, rangeFirst(entry, index));
            try testing.expectEqual(range.last, rangeLast(entry, index));
        }
        if (bit == 63) break;
    }

    var mask_index: usize = 0;
    while (mask_index < maskEntryCount()) : (mask_index += 1) {
        const mask_entry = maskEntryAt(mask_index);
        var collector: Collector = .{ .allocator = allocator };
        defer collector.ranges.deinit(allocator);
        try forEachRun(mask_entry.mask, 0, &collector, Collector.append);
        try testing.expectEqual(
            @as(usize, mask_entry.ranges.count),
            collector.ranges.items.len,
        );
        for (collector.ranges.items, 0..) |range, index| {
            try testing.expectEqual(
                range.first,
                rangeFirst(mask_entry.ranges, index),
            );
            try testing.expectEqual(
                range.last,
                rangeLast(mask_entry.ranges, index),
            );
        }
    }
}

test "flat categories match the packed table" {
    const testing = @import("std").testing;
    var codepoint: u32 = 0;
    while (codepoint <= 0x1fffff) : (codepoint += 1) {
        const value_codepoint: u21 = @intCast(codepoint);
        const expected: Category = @enumFromInt(
            @as(u5, @truncate(value(value_codepoint))),
        );
        try testing.expectEqual(expected, category(value_codepoint));
    }
}
